// scanAuditUsers scans rows into AuditUser entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanAuditUsers(rows database.Rows, columns []string) ([]*AuditUser, error) {
	var result []*AuditUser
	for rows.Next() {
		a := &AuditUser{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "id":
				targets[idx] = &a.ID
			case "action":
				targets[idx] = &a.Action
			case "details":
				targets[idx] = &a.Details
			case "created_at":
				targets[idx] = &a.CreatedAt
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan user: %w", err)
		}

		result = append(result, a)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate user rows: %w", err)
	}
	return result, nil
}

