// encodeProductTagLabelCursor encodes cursor key values as a base64 JSON string.
func encodeProductTagLabelCursor(keys []string, p *ProductTagLabel) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "product_id":
			out["product_id"] = p.ProductID
		case "tag_name":
			out["tag_name"] = p.TagName
		case "label":
			out["label"] = p.Label
		case "description":
			out["description"] = p.Description
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode product_tag_label cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

