var userCategoryAllColumns = []string{"category_id", "user_id"}

// scanUserCategories scans rows into UserCategory entities using a column-name switch.
// Handles both scan target shapes (direct, wrapped) without reflection.
func scanUserCategories(rows database.Rows, columns []string) ([]*UserCategory, error) {
	var result []*UserCategory
	for rows.Next() {
		u := &UserCategory{}

		targets := make([]any, len(columns))
		for idx, col := range columns {
			switch col {
			case "user_id":
				targets[idx] = &u.UserID
			case "category_id":
				targets[idx] = &u.CategoryID
			}
		}

		if err := rows.Scan(targets...); err != nil {
			return nil, fmt.Errorf("scan user_category: %w", err)
		}

		result = append(result, u)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate user_category rows: %w", err)
	}
	return result, nil
}

