// Paginate returns a page of warehouses with total count for offset-based pagination.
// A nil filter paginates all warehouses.
func (c *warehouseClient) Paginate(ctx context.Context, input PaginateInput[WarehouseFilter], opts ...func(*CallOptions[WarehouseFieldOptions])) (*PaginateResult[Warehouse], error) {
	options := resolveCallOptions(opts)
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpPaginate, Table: TableWarehouses, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[WarehouseFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Total count (delegates to Count — both are always generated)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate warehouses count: %w", err)
		}

		// Page data via GetMany (handles FieldOptions and relationships)
		warehouses, err := c.GetMany(ctx, &GetWarehousesInput{
			Filter: input.Filter,
			Sorts:  input.Sort,
			Limit:  &input.Limit,
			Offset: &input.Offset,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("paginate warehouses: %w", err)
		}

		return &PaginateResult[Warehouse]{
			Items:      warehouses,
			TotalCount: totalCount,
			Offset:     input.Offset,
			Limit:      input.Limit,
			HasMore:    int64(input.Offset+input.Limit) < totalCount,
		}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*PaginateResult[Warehouse]), nil
}

// Connection returns a Relay-style cursor-paginated connection of warehouses.
// Sort order is determined by cursor_keys — custom sorts are not supported.
// Use Paginate for custom sort orders.
func (c *warehouseClient) Connection(ctx context.Context, input ConnectionInput[WarehouseFilter], opts ...func(*CallOptions[WarehouseFieldOptions])) (*Connection[Warehouse], error) {
	options := resolveCallOptions(opts)

	if options.LockMode != sql.LockNone {
		if !database.InTransaction(ctx) {
			return nil, fmt.Errorf("connection warehouses: LockMode requires an active transaction")
		}
		options.SkipCache = true
	}
	result, err := c.executeQuery(ctx, options.SkipHooks, &hook.QueryContext{
		Op: hook.OpConnection, Table: TableWarehouses, Schema: "public",
		Input: input, CallOptions: options,
	}, func(ctx context.Context, q *hook.QueryContext) (any, error) {
		// Internal calls with SkipHooks to prevent nested hook invocation
		internalOpts := func(o *CallOptions[WarehouseFieldOptions]) {
			*o = options
			o.SkipHooks = true
		}

		// Validate: first and last are mutually exclusive
		if input.First != nil && input.Last != nil {
			return nil, ErrInvalidCursor
		}

		// Total count (separate COUNT query — no cursor conditions)
		totalCount, err := c.Count(ctx, input.Filter, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection warehouses count: %w", err)
		}

		// Decode cursors and build keyset conditions
		var keysetConds []sql.Condition
		if input.After != nil {
			cursor, err := decodeCursor(*input.After)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, ">"))
		}
		if input.Before != nil {
			cursor, err := decodeCursor(*input.Before)
			if err != nil {
				return nil, ErrInvalidCursor
			}
			keysetConds = append(keysetConds, cursorKeyset(c.dialect, c.cursorKeys, cursor, "<"))
		}

		// Direction and limit
		limit := c.pageSize
		ascending := true
		if input.First != nil {
			limit = *input.First
		} else if input.Last != nil {
			limit = *input.Last
			ascending = false
		}

		// Fetch limit+1 rows via GetMany (handles FieldOptions, O2O joins, relationships, soft delete)
		connLimit := limit + 1
		warehouses, err := c.GetMany(ctx, &GetWarehousesInput{
			Filter:     input.Filter,
			Sorts:      cursorSorts(c.cursorKeys, ascending),
			Limit:      &connLimit,
			conditions: keysetConds,
			// Each edge's cursor is encoded from the row it wraps, so the cursor
			// keys have to survive a narrowed FieldOptions — otherwise the
			// encoder reads fields the SELECT never filled and every cursor
			// carries zero values.
			requiredColumns: c.cursorKeys,
		}, internalOpts)
		if err != nil {
			return nil, fmt.Errorf("connection warehouses: %w", err)
		}

		// Trim extra row and determine page boundaries
		hasMore := len(warehouses) > limit
		if hasMore {
			warehouses = warehouses[:limit]
		}

		// Backward pagination: reverse for ascending cursor order
		if !ascending {
			slices.Reverse(warehouses)
		}

		// Build edges with encoded cursors
		edges := make([]Edge[Warehouse], len(warehouses))
		for i, row := range warehouses {
			cursor, err := encodeWarehouseCursor(c.cursorKeys, row)
			if err != nil {
				return nil, err
			}
			edges[i] = Edge[Warehouse]{
				Node:   row,
				Cursor: cursor,
			}
		}

		pageInfo := PageInfo{
			HasNextPage:     (ascending && hasMore) || (!ascending && input.Before != nil),
			HasPreviousPage: (!ascending && hasMore) || (ascending && input.After != nil),
		}
		if len(edges) > 0 {
			pageInfo.StartCursor = &edges[0].Cursor
			pageInfo.EndCursor = &edges[len(edges)-1].Cursor
		}

		return &Connection[Warehouse]{Edges: edges, PageInfo: pageInfo, TotalCount: totalCount}, nil
	})
	if err != nil {
		return nil, err
	}
	return result.(*Connection[Warehouse]), nil
}

// encodeWarehouseCursor encodes cursor key values as a base64 JSON string.
func encodeWarehouseCursor(keys []string, w *Warehouse) (string, error) {
	out := make(map[string]any, len(keys))
	for _, key := range keys {
		switch key {
		case "id":
			out["id"] = w.ID
		case "external_id":
			out["external_id"] = w.ExternalID
		case "name":
			out["name"] = w.Name
		case "price":
			out["price"] = w.Price
		case "nullable_price":
			out["nullable_price"] = w.NullablePrice
		case "related_ids":
			out["related_ids"] = w.RelatedIDS
		case "nullable_ref":
			out["nullable_ref"] = w.NullableRef
		case "allowed_roles":
			out["allowed_roles"] = w.AllowedRoles
		case "created_at":
			out["created_at"] = w.CreatedAt
		}
	}
	data, err := json.Marshal(out)
	if err != nil {
		return "", fmt.Errorf("encode warehouse cursor: %w", err)
	}
	return base64.StdEncoding.EncodeToString(data), nil
}

